.page-header {
  width: 100%;
  max-width: 480px;
  margin-bottom: 1.5rem;
  text-align: center;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.page-header p {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
}

/* Card */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-radius: calc(var(--radius) * 1.5);
  box-shadow: var(--shadow-card-lg);
  padding: 2rem;
}

