  width: 100%;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-family: inherit;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--color-btn);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color var(--transition), box-shadow var(--transition);
  outline: none;
