+  color: var(--color-text-secondary);
+  display: flex;
+  align-items: flex-start;
+  gap: 0.3em;
+}
+
+.field-error {
+  font-size: 0.8125rem;
+  color: var(--color-error);
+  display: none;
+  align-items: flex-start;
+  gap: 0.3em;
+}
+
+.field-error[aria-hidden="false"],
