+  display: flex;
+}
+
+.field-error svg,
+.field-hint svg {
+  flex-shrink: 0;
+  margin-top: 0.1em;
+}
+
+/* Submit button */
+.btn-submit {
+  margin-top: 0.5rem;
+  width: 100%;
+  padding: 0.75rem 1.5rem;
+  font-size: 0.9375rem;
+  font-family: inherit;
+  font-weight: 600;
+  color: #ffffff;
+  background-color: var(--color-btn);
+  border: none;
+  border-radius: var(--radius);
+  cursor: pointer;
+  transition: background-color var(--transition), box-shadow var(--transition);
