+  outline: 2px solid transparent;
+}
+
+.btn-submit:active {
+  background-color: #2f42b8;
+}
+
+/* Status message */
+.form-status {
+  border-radius: var(--radius);
+  padding: 0.875rem 1rem;
+  font-size: 0.9rem;
+  font-weight: 500;
+  display: none;
