  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f5f7fa;
  --color-surface: #ffffff;
  --color-border: #d1d5db;
  --color-border-focus: #4f6ef7;
  --color-text: #111827;
  --color-text-secondary: #6b7280;
  --color-required: #b91c1c;
  --color-error: #b91c1c;
  --color-error-bg: #fef2f2;
  --color-error-border: #fca5a5;
  --color-success: #166534;
  --color-success-bg: #f0fdf4;
  --color-success-border: #86efac;
  --color-btn: #4f6ef7;
  --color-btn-hover: #3b54d4;
  --color-btn-focus-ring: #a5b4fc;
  --radius: 0.5rem;
  --shadow-card: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-card-lg: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --transition: 150ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.5;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--color-btn);
  color: #fff;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  outline: none;
}

.skip-link:focus {
  top: 1rem;
}

/* Page header */
.page-header {
  width: 100%;
  max-width: 480px;
  margin-bottom: 1.5rem;
  text-align: center;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.page-header p {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
}

/* Card */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-radius: calc(var(--radius) * 1.5);
  box-shadow: var(--shadow-card-lg);
  padding: 2rem;
}

/* Form */
.contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Form field wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

/* Label */
.form-field label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-indicator {
  color: var(--color-required);
  margin-left: 0.2em;
  aria-hidden: true;
}

/* Input */
.form-field input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 0.9375rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  transition: border-color var(--transition), box-shadow var(--transition),
    background-color var(--transition);
  outline: none;
  min-width: 0;
}

.form-field input::placeholder {
  color: #9ca3af;
}

.form-field input:hover {
  border-color: #9ca3af;
}

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px var(--color-btn-focus-ring);
  outline: 2px solid transparent;
}

/* Error state */
.form-field input[aria-invalid="true"] {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

.form-field input[aria-invalid="true"]:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px #fecaca;
}

/* Helper and error text */
.field-hint {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  display: flex;
  align-items: flex-start;
  gap: 0.3em;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  display: none;
  align-items: flex-start;
  gap: 0.3em;
}

.field-error[aria-hidden="false"],
.field-error:not([aria-hidden]) {
  display: flex;
}

.field-error svg,
.field-hint svg {
  flex-shrink: 0;
  margin-top: 0.1em;
}

/* Submit button */
.btn-submit {
  margin-top: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-family: inherit;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--color-btn);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color var(--transition), box-shadow var(--transition);
  outline: none;
}

.btn-submit:hover {
  background-color: var(--color-btn-hover);
}

.btn-submit:focus-visible {
  box-shadow: 0 0 0 3px var(--color-btn-focus-ring);
  outline: 2px solid transparent;
}

.btn-submit:active {
  background-color: #2f42b8;
}

/* Status message */
.form-status {
  border-radius: var(--radius);
  padding: 0.875rem 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  display: none;
  align-items: flex-start;
  gap: 0.625rem;
}

.form-status[aria-hidden="false"] {
  display: flex;
}

.form-status--success {
  background-color: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  color: var(--color-success);
}

.form-status--error {
  background-color: var(--color-error-bg);
  border: 1.5px solid var(--color-error-border);
  color: var(--color-error);
}

.form-status svg {
  flex-shrink: 0;
  margin-top: 0.1em;
}

/* Forced colors */
@media (forced-colors: active) {
  .form-field input {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
    background: Canvas;
    color: CanvasText;
  }

  .form-field input:focus {
    outline: 3px solid Highlight;
    box-shadow: none;
  }

  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }

  .btn-submit:focus-visible {
    outline: 3px solid Highlight;
    box-shadow: none;
  }
}

/* Screen-reader only utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Reflow at 320px */
@media (max-width: 360px) {
  .card {
    padding: 1.25rem 1rem;
  }
}
