  text-align: center;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.page-header p {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
}

/* Card */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-radius: calc(var(--radius) * 1.5);
  box-shadow: var(--shadow-card-lg);
  padding: 2rem;
}

/* Form */
.contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Form field wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

/* Label */
.form-field label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-indicator {
  color: var(--color-required);
  margin-left: 0.2em;
  aria-hidden: true;
}

/* Input */
.form-field input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 0.9375rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  transition: border-color var(--transition), box-shadow var(--transition),
