  outline: none;
  min-width: 0;
}

.form-field input::placeholder {
  color: #9ca3af;
}

.form-field input:hover {
  border-color: #9ca3af;
}

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px var(--color-btn-focus-ring);
  outline: 2px solid transparent;
}

